import 'package:flutter/material.dart';
import 'package:sehatak/core/models/dental/dental_models.dart';
import 'package:sehatak/core/services/dental_service.dart';
class DentalDoctorDetailScreen extends StatelessWidget { final String doctorId; const DentalDoctorDetailScreen({super.key,required this.doctorId}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل طبيب الأسنان')),body:FutureBuilder<DentalDoctor?>(future:DentalService().getDoctor(doctorId),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data;if(d==null)return const Center(child:Text('الطبيب غير متوفر'));return ListView(padding:const EdgeInsets.all(16),children:[Text(d.name,textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text(d.specialty,textAlign:TextAlign.center),Text('التقييم: ${d.rating.toStringAsFixed(1)}'),Text('الخبرة: ${d.experienceYears} سنة'),Text('العنوان: ${d.address}'),Text('الهاتف: ${d.phone}')]);}));} }
